import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    # The first nonempty record is the single header record.
    for columns in reader:
        if columns:
            break
    else:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(len(columns), max((len(row) for row in rows), default=0))

    # Preserve surplus fields without shifting or discarding any values.
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
